package br.com.omnilog;
import br.com.omnilog.domain.*;import br.com.omnilog.structures.*;import br.com.omnilog.payments.*;import java.math.BigDecimal;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class DomainTest {@Test void vehiclePolymorphism(){Veiculo van=new VanUtilitaria("VAN-1",new BigDecimal("1000"));Veiculo drone=new DroneEntrega("DR-1",new BigDecimal("5"));assertNotEquals(van.calcularCustoFrete(new BigDecimal("10"),new BigDecimal("2")),drone.calcularCustoFrete(new BigDecimal("10"),new BigDecimal("2")));}@Test void rejectOverCapacity(){Veiculo v=new CaminhaoFrigorifico("C-1",new BigDecimal("100"));assertThrows(IllegalArgumentException.class,()->v.calcularCustoFrete(BigDecimal.ONE,new BigDecimal("101")));}@Test void stackIsLifo(){HistoricoOperador h=new HistoricoOperador();h.registrar("A");h.registrar("B");assertEquals("B",h.voltar().orElseThrow());}@Test void queueIsFifo(){FilaDespacho q=new FilaDespacho();q.enfileirar("P1");q.enfileirar("P2");assertEquals("P1",q.despachar().orElseThrow());}@Test void boletoIsPending(){var r=new BoletoBancario().processar(new BigDecimal("10"),"REF-1");assertFalse(r.aprovado());}}
